import CryptoKit
import XCTest
import PlanariumDomain
@testable import PlanariumPresets

/// Raster version 1 of the surface format, frozen. The fixture was written once by the production
/// writer at raster version 1 (before any later change) and is never regenerated by a test. Every
/// count and digest below is a literal. A change of the rasteriser (predicate, epsilon, trigonometry,
/// order) must raise `SurfaceRasterizer.currentVersion`, keep this version's function and add a new fixture.
final class SurfaceV7GoldenTests: XCTestCase {
    private func id(_ n: Int) -> UUID { UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))! }
    private static let fixtureSHA256 = "e5d6a1e7bb468b8b556befd65ca71de1ddbe9f1cf71158e902d608228556e06a"

    private func fixtureData() throws -> Data {
        let url = try XCTUnwrap(Bundle.module.resourceURL?.appendingPathComponent("Fixtures/SurfaceV7/surface-v7-raster1.sickpreset.json"))
        return try Data(contentsOf: url)
    }
    private func live() throws -> InstrumentDocument {
        let layer = SpatialDocumentLayer(id: UUID(), name: "Live", color: .orange, isVisible: true, isActive: true, isLocked: false,
            isSoloed: false, cells: [PolarDeviceLattice(ring: 60, sector: 180)!],
            routings: [SpatialRouting(target: .midiNote(channel: 0), program: .singleNote(note: 60, velocity: 100, transition: .retrigger))], cellOverrides: [:])
        return InstrumentDocument(spatial: try SpatialDocument(latticeVersion: .polarDeviceV2, layers: [layer], selectedLayerID: layer.id),
                                  revision: .init(session: UUID(), counter: 1))
    }
    private func read() throws -> (PresetReading, InstrumentDocument) {
        let reading: PresetReading
        switch PresetDocumentReader.read(try fixtureData()) {
        case .success(let value): reading = value
        case .failure(let error): throw error
        }
        return (reading, try reading.replacing(try live()))
    }

    func testTheFixtureFileIsTheFrozenOne() throws {
        XCTAssertEqual(SHA256.hash(data: try fixtureData()).map { String(format: "%02x", $0) }.joined(), Self.fixtureSHA256,
                       "The frozen fixture changed. Never regenerate it for a changed rasteriser: raise the raster version and add a new fixture.")
        XCTAssertEqual(SurfaceRasterizer.currentVersion, 1, "Another raster version needs its own fixture; version 1 stays readable")
    }

    func testFrozenVersion1OriginalsCountsAndDigestsReadFromTheRealReader() throws {
        let (reading, document) = try read()
        XCTAssertEqual(reading.sourceVersion, 7)
        let surfaces = document.spatial.layers.flatMap(\.surfaces)
        XCTAssertEqual(surfaces.map(\.id), [11, 12, 13, 14, 15, 16, 17, 2].map(id))

        // (surface, cell count, digest) — literals from the frozen file, not computed here.
        let golden: [(Int, Int, String)] = [
            (11, 919, "9c906811e2a0de1a"), (12, 955, "de269f2fa8081ff2"), (13, 532, "12de43d4a15ba89d"),
            (14, 3900, "79820c46e6179c35"), (15, 912, "7d492b98699394b1"), (16, 577, "b057fcde68eecac2"),
            (17, 201, "e0fa73d3bdd1a481"), (2, 2, "916782ae6149f81d"),
        ]
        for (number, count, digest) in golden {
            let surface = try XCTUnwrap(surfaces.first { $0.id == id(number) })
            XCTAssertEqual(surface.derivation.rasterVersion, 1, "surface \(number)")
            XCTAssertEqual(surface.cells.count, count, "cell count of surface \(number)")
            XCTAssertEqual(surface.derivation.digestText, digest, "digest of surface \(number)")
        }

        // Original forms, exactly as authored.
        XCTAssertEqual(surfaces[0].form, .shape(.rectangle(widthCm: 40, heightCm: 20), .init(xCm: 5, yCm: 100, rotationDegrees: 30, mirrorX: true)))
        XCTAssertEqual(surfaces[1].form, .shape(.circle(radiusCm: 15), .init(xCm: -30, yCm: 80)))
        XCTAssertEqual(surfaces[2].form, .shape(.polygon(pointsCm: [.init(x: 0, y: 0), .init(x: 40, y: 0), .init(x: 40, y: 10),
                                                                    .init(x: 10, y: 10), .init(x: 10, y: 30), .init(x: 0, y: 30)]),
                                                 .init(xCm: 20, yCm: 120, rotationDegrees: -20)))
        XCTAssertEqual(surfaces[3].form, .shape(.ringSector(fromCm: 60, toCm: 90, fromDegrees: -40, toDegrees: 25), .identity))
        // Shapes whose edges pass exactly through grid points (x = 0 line, quarter turns): the edge rule decides.
        XCTAssertEqual(surfaces[4].form, .shape(.rectangle(widthCm: 40, heightCm: 20), .init(xCm: 0, yCm: 100)))
        XCTAssertEqual(surfaces[5].form, .shape(.rectangle(widthCm: 30, heightCm: 10), .init(xCm: 10, yCm: 60, rotationDegrees: 90, mirrorX: true)))
        XCTAssertEqual(surfaces[6].form, .shape(.circle(radiusCm: 10), .init(xCm: 0, yCm: 180)))
        // The exact mask: cells and its per-cell override are primary data.
        let cellA = PolarDeviceLattice(ring: 50, sector: 180)!, cellB = PolarDeviceLattice(ring: 51, sector: 181)!
        XCTAssertEqual(surfaces[7].form, .legacyMask(.init(cells: [cellA, cellB],
            cellOverrides: [cellA: [.init(target: .midiNote(channel: 0), value: .note(number: 70, velocity: 80))]])))
        XCTAssertEqual(surfaces[0].presentation.valueColors, [.orange, .green, .blue])
        XCTAssertEqual(surfaces[0].routings.map(\.id), [101, 102].map(id))
        XCTAssertEqual(surfaces[0].routings[1].program, .continuous(minimum: 0.1, maximum: 0.9, directionDegrees: 33.5, curve: .linear))
    }

    /// The established preset parts travel through the same V7 container.
    func testMixerSoundsScenesTempoAndViewportSurviveInTheVersion7File() throws {
        let (reading, document) = try read()
        XCTAssertEqual(reading.name, "Surface V7 golden")
        XCTAssertEqual(reading.summary, "Frozen raster version 1")
        XCTAssertEqual(reading.viewport?.centerXMeters, 0.25)
        XCTAssertEqual(reading.viewport?.centerYMeters, 1.5)
        XCTAssertEqual(reading.viewport?.metersPerPoint, 0.004)
        XCTAssertEqual(document.beatsPerMinute, 97.5)
        XCTAssertEqual(document.masterLevelDecibels, -3)
        XCTAssertEqual(document.midiTarget, .init(uniqueID: 4242))
        let channel = try XCTUnwrap(document.channels.first)
        XCTAssertEqual(document.channels.count, 1)
        XCTAssertEqual(channel.id, id(200)); XCTAssertEqual(channel.name, "Keys"); XCTAssertEqual(channel.color, .green)
        XCTAssertEqual(channel.levelDecibels, -4.5); XCTAssertEqual(channel.pan, 0.25); XCTAssertTrue(channel.soloed)
        XCTAssertEqual(channel.instrument?.state, Data([1, 2, 3, 4, 5]))
        XCTAssertEqual(channel.instrument?.identity, .init(componentType: 0x61756D75, componentSubType: 0x61626364, componentManufacturer: 0x44656D6F))
        XCTAssertEqual(channel.inserts.map(\.id), [id(201)]); XCTAssertEqual(channel.inserts[0].plugin.state, Data([9, 8]))
        XCTAssertTrue(channel.inserts[0].bypassed)
        XCTAssertEqual(channel.midiEffects.map(\.id), [id(202)]); XCTAssertEqual(channel.midiEffects[0].chord.root, 2)
        XCTAssertEqual(document.scenes.map(\.name), ["Both", "Shapes only"])
        XCTAssertEqual(document.scenes[0].activeLayerIDs, [id(1), id(2)]); XCTAssertEqual(document.scenes[1].activeLayerIDs, [id(1)])
        XCTAssertEqual(document.currentSceneID, id(302))
        XCTAssertEqual(document.revision, .init(session: id(900), counter: 7))
        XCTAssertEqual(document.spatial.layers.map(\.id), [id(1), id(2)])
        XCTAssertEqual(document.spatial.layers.map(\.name), ["Shapes", "Mask"])
    }

    /// Reading and writing the frozen file again changes no byte of the stored originals.
    func testReadingAndWritingTheFrozenFileAgainIsByteIdentical() throws {
        let data = try fixtureData()
        let (reading, document) = try read()
        let again = try PresetDocumentWriter.encode(.init(name: reading.name, document: document,
            viewport: reading.viewport, summary: reading.summary))
        XCTAssertEqual(again, data)
    }

    /// A rasteriser that decided differently would make the stored file unreadable: the file is
    /// refused as a whole instead of being repaired (guards the failure mode the digest exists for).
    func testADifferentRasterisationOfTheStoredOriginalIsRefusedNotRepaired() throws {
        var text = String(decoding: try fixtureData(), as: UTF8.self)
        text = text.replacingOccurrences(of: "9c906811e2a0de1a", with: "9c906811e2a0de1b")
        guard case .failure(let error) = PresetDocumentReader.read(Data(text.utf8)) else { return XCTFail("a changed digest was accepted") }
        XCTAssertEqual(error, .surfaceDerivationMismatch(surfaceID: id(11)))
    }
}
